programs.sol:
"""A document-opening response, plus a few explicit formatting signals.

At the start of a document, function words and heading marks are negative;
whitespace, escapes, and long or non-ASCII words tend to be positive. PHP's
opening tag and initial NULs/escaped tabs give much larger responses.
Away from the opening, only explicit tool-call tags, the opening thought tag, and doubled middle
dots are modeled. The many smaller, word-specific responses are omitted.
"""
READS = ()

ARTICLES = {'a', 'an', 'the'}
AUXILIARIES = {
    'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'have', 'has', 'had', 'do', 'does', 'did', 'can', 'could',
    'shall', 'should', 'will', 'would', 'may', 'might', 'must',
}
PREPOSITIONS = {
    'in', 'on', 'at', 'of', 'to', 'for', 'from', 'with', 'by', 'as',
    'into', 'over', 'under', 'through', 'between', 'without', 'within',
    'about', 'against', 'during', 'after', 'before',
}
PRONOUNS = {
    'i', 'you', 'he', 'she', 'it', 'we', 'they', 'me', 'him', 'her',
    'us', 'them', 'my', 'your', 'his', 'its', 'our', 'their',
}


def opening_value(token):
    word = token.strip().lower()
    if word in ARTICLES:
        return -0.40
    if word in AUXILIARIES:
        return -0.29
    if word in PREPOSITIONS:
        return -0.09
    if word in PRONOUNS:
        return -0.13
    if token and not token.strip('#'):
        return -0.55
    # Source-file opening syntax: imports, includes, and a shell shebang.
    if token in {'package', 'import'}:
        return -0.77
    if token == '#include':
        return 0.43
    if token == '#!/':
        return -0.63
    if token.isspace():
        return 0.51 if '\t' in token else 0.20
    if token.startswith('\\'):
        return 0.54
    if '\ufffd' in token:
        return -0.05
    if not token.isascii():
        return 0.14
    if len(word) >= 6 and word.isalpha():
        return 0.17
    return 0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, previous, uniform = 0, '', True
    else:
        _, n, previous, uniform = carry
        uniform = uniform and token == previous

    value = opening_value(token) if n == 0 else 0.0
    if token == '··':
        value = -0.54
    elif token == '<tool_call>':
        value = 0.092
    elif token == '</tool_call>':
        value = -0.071
    elif token == '<think>':
        value = 0.074
    elif uniform and token == '\x00':
        value = 2.707
    elif uniform and token == '\\t':
        value = 1.59
    elif n == 0 and token == '<?':
        value = 0.341
    elif n == 1 and previous == '<?' and token == 'php':
        value = 1.525
    return (doc, n + 1, token, uniform), value

"""Approximate the response to two-letter word beginnings.

Latin and Cyrillic letter pairs are negative at word boundaries, but mostly
quiet inside words. Frequent short words are spared; Latin capitals are more
negative. Conversation-control markers have separate responses. Uncommon
words receive a small extra negative bias at the first two document positions.
This leaves token-specific variation, especially opening bigrams, unexplained.
"""
import re
import string
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
CONTROL = {
    '<|im_start|>': 1.48,
    '<|im_end|>': -0.13,
    '<think>': 1.52,
    '</think>': 1.02,
    '<tool_call>': 0.82,
    '</tool_call>': 0.06,
    '<tool_response>': 0.81,
    '</tool_response>': 1.41,
}
PAIR = re.compile(r'([\W_]*)([A-Za-z]{2})\Z')


def cyrillic(char):
    return bool(char) and 'CYRILLIC' in unicodedata.name(char, '')


@lru_cache(maxsize=8192)
def short_word(text):
    match = PAIR.fullmatch(text)
    if not match:
        return None
    lead, word = match.groups()
    low = word.lower()
    frequency = max(zipf_frequency(low, 'en'), max(
        zipf_frequency(low, lang) - 0.8
        for lang in ('de', 'es', 'fr', 'it', 'pt')))
    common = max(0.0, min(1.0, (frequency - 4.5) / 2.5))
    return lead, word, common


def pair_value(lead, word, common, continuation):
    if not lead and continuation:
        return -0.03
    value = -0.385 + 0.307 * common
    value -= 0.225 * word.isupper() + 0.092 * word.istitle()
    if lead.isspace():
        value += -0.055 + 0.133 * common
    elif lead:
        value += 0.098 - 0.215 * common
    return value


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    last = previous[-1:]
    continuation = last.isascii() and last.isalpha()
    value = CONTROL.get(text, 0.0)
    pair = short_word(text)
    if pair is not None:
        lead, word, common = pair
        value = pair_value(*pair, continuation)
        # Contractions and ordinal suffixes continue an existing word/number.
        if (lead in ("'", "’") and word.lower() in ('ll', 're', 've')
                and continuation):
            value = 0.0
        if (last.isdigit() and not lead
                and word.lower() in ('st', 'nd', 'rd', 'th')):
            value = 0.0
    else:
        word = text.lstrip(string.whitespace + string.punctuation)
        if len(word) == 2 and all(cyrillic(c) for c in word):
            if word == text and cyrillic(last):
                value = 0.0
            else:
                common = max(0.0, min(1.0,
                    (zipf_frequency(word.lower(), 'ru') - 5.8) / 1.4))
                value = -0.40 * (1.0 - common)
    if text == '<|im_start|>' and position == 0:
        value = 0.10
    if previous == '<|im_start|>':
        if text == 'assistant':
            value = -0.15 if position == 1 else -0.48
        elif text == 'user':
            value = 0.10 if position == 1 else -0.37
        elif text == 'system':
            value = -0.10
    if position < 2 and text not in CONTROL and previous != '<|im_start|>':
        word = text.strip(string.whitespace + string.punctuation)
        if word.isalpha():
            frequency = zipf_frequency(word, 'en')
            rarity = max(0.0, min(1.0, (7.4 - frequency) / 4))
            value -= (0.35 if position == 0 else 0.20) * rarity
    return (doc, position + 1, text), float(value)

"""Respond mainly to standalone separator spaces, not merged word spaces.

The preceding text matters: numbers, dates, reference labels, indentation,
opening quotes and comment/diff margins weaken the response. Repeated double-spacing
reduces it too. Other tokens are near zero, except for negative predictions
on blank lines beside thinking tags.
"""
import calendar
import re
import regex

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name, *calendar.month_abbr) if s}
FIGURES = {'fig', 'figs', 'figure', 'figures', 'table', 'tables'}
REFERENCES = {'eq', 'equation', 'section', 'sec', 'chapter', 'algorithm',
              'theorem', 'lemma', 'rule', 'example', 'case', 'line', 'test'}
PREPOSITIONS = {'in', 'of', 'to', 'at', 'by', 'for', 'with', 'from', 'about',
                'since', 'between', 'under', 'over', 'around', 'than'}
OPERATORS = {'=', '==', '===', '!=', '+', '-', '*', '/', '<', '>'}
DATE_END = re.compile(r'\b(?:' + '|'.join(MONTHS) +
                      r')\s+\d+(?:st|nd|rd|th)?,$', re.I)
EAST_ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]$')
OPEN_QUOTE = re.compile(r'''(?:^|[\s(=,:])(?:[rfbuRFBU]{0,2})\\?['"]$''')


def spacing_group(s):
    """Separate spacing conventions for words, sentence ends, and commas."""
    if s.endswith(('.', '!', '?')):
        return 1
    if s.strip() == ',':
        return 2
    return 0 if s[-1:].isalpha() else 3


def separator_value(previous, before, text):
    words = re.findall(r'[^\W\d_]+', text.lower())
    word = words[-1] if words else ''
    line = text.replace('\\n', '\n').replace('\\t', '\t').rsplit('\n', 1)[-1]
    if not previous:
        return -0.22
    if text.endswith('\\n'):
        return -0.72
    if previous.isspace() or '\n' in previous:
        if '\xa0' in previous:
            return 0.4
        return -0.15 if previous.endswith('\n') else -0.03
    if previous[-1:].isdecimal():
        return -0.06
    if re.search(r'\d(?:st|nd|rd|th)$', text, re.I):
        return -0.35
    if DATE_END.search(text):
        return 0.18
    if text[-1:].isalpha() or text.endswith('.'):
        if word in MONTHS or word in FIGURES:
            return 0.12
        if word in REFERENCES:
            return 0.4
    if regex.search(r'\p{Thai}$', text):
        return 0.0
    if EAST_ASIAN.search(text):
        return 0.4
    if text.endswith(('。', '、', '，', '：', '；')):
        return 0.15
    if OPEN_QUOTE.search(text) and line.count(text[-1]) % 2:
        return -0.35
    if line.strip() in {'*', '//', '+'}:
        return -0.4
    if previous == '.' and before[-1:].isdigit():
        return -0.4 if re.match(r'^[\s>]*\d+\.$', line) else 0.4
    if previous.strip() == ',':
        return 0.73
    if previous.strip() == '|':
        return 0.35
    if previous.strip() in {'[', ']'}:
        return 0.2
    if previous.strip() in OPERATORS:
        return 0.6
    if previous.strip().endswith(':'):
        return 0.87
    if word in PREPOSITIONS or word in {'is', 'was', 'are', 'were', 'a', 'an'}:
        return 1.0
    if word in {'and', 'or'}:
        return 0.77
    return 0.82 if any(c.isalnum() for c in previous) else 0.62


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, tail = '', '', b''
        counts, doubles = [0]*3, [0]*3
    else:
        _, previous, before, tail, counts, doubles = carry
    if previous == ' ' and s.startswith(' ') and spacing_group(before) < 3:
        doubles[spacing_group(before)] += 1
    value = 0.001
    if s == '\n\n' and previous in {'<think>', '</think>'}:
        value = -0.25
    if s == ' ':
        value = separator_value(previous, before, tail.decode('utf-8', 'ignore'))
        k = spacing_group(previous)
        if previous and '\n' not in previous and k < 3:
            if value > 0.3:
                rate = min(1.0, 1.5*doubles[k]/(counts[k]+2))
                value -= (value+0.2)*rate
            counts[k] += 1
    tail = (tail + prefix.token_bytes[-1])[-128:]
    return (doc, s, previous, tail, counts, doubles), value

"""Sparse lexical cues, not a general semantic classifier.

Positive: Chinese kinship words, milk, aromatic vegetables and the
single Han characters read gài in Mandarin (as in 概/盖). Negative:
short cre/cri spellings,
vowel continuations after co-, and the Thai syllables มี (have), ดี (good).
A document-opening Title: has a strong positive colon. Other positions
are near zero. Split Han characters are joined; a separately arriving
second byte after a space-prefixed Han lead byte has its own response
for the aromatic/female-family prefixes.
State keeps the document position, a short text tail and unfinished UTF-8.
"""
import codecs
from functools import lru_cache

import regex
from pypinyin import Style, lazy_pinyin

READS = ()
# Shared UTF-8 prefixes of ginger, scallion and garlic.
GINGER = "姜".encode()[:2]
ALLIUMS = {c.encode()[:2] for c in "葱蒜"}


@lru_cache(maxsize=4096)
def pronounced_gai(word):
    return bool(regex.fullmatch(r'\p{Script=Han}', word)) and (
        lazy_pinyin(word, style=Style.TONE3)[0] == 'gai4'
    )


def chinese(word, previous):
    if word in {'姐', '姉'}:
        return 3.7
    if word == '哥':
        return 1.4 if previous.endswith(('小', '二')) else 3.3
    if word in {'姨', '姑'}:
        return 3.1
    if word == '妹':
        return 1.8
    if word in {'哥哥', '姐姐', '妹妹', '姑娘', '小姐姐'}:
        return 1.7
    if word in {'女儿', '女兒', '小姐', '嫂'}:
        return 1.4
    if word in {'娘', '奶奶'}:
        return 2.3
    if word == '大姐':
        return 3.8
    if word in {'弟', '弟弟', '妹子', '婆', '外婆', '媽', '妈'}:
        return 0.7
    if word in {'兄', '爸', '大哥'}:
        return 1.0
    # Milk/breasts; 大奶 literally means large breasts.
    if word == '奶':
        return 4.4 if previous.endswith('大') else 2.0
    # Ginger, scallion and garlic: the classic Chinese aromatic trio.
    if word in {'姜', '葱', '蒜'}:
        return 5.0
    if word == '大蒜':
        return 2.8
    if word in {'莱', '萊', '葛'}:  # goosefoot and kudzu
        return 1.3
    if word == '菜':
        return 1.3
    if word == '蛋':
        return 0.8
    if pronounced_gai(word):
        return 1.6
    if word == '大概':
        return 2.3
    if word in {'大约', '大約'}:
        return 1.1
    return 0.0


def spelling(token, previous, tail):
    s, p = token.strip(), previous.strip().lower()
    # Fragmented velar + liquid + vowel spellings in several scripts.
    if p == 'c':
        if s == 'rie': return -7.7
        if s == 'rea': return -3.4
        if s == 'ria': return -2.4
        if s == 'oe': return -3.8
    if p == 'k' and s == 'rie':
        return -3.3
    if p == 'к' and s.lower() == 'ре':
        return -2.3
    if tail.lower().endswith('cri') and s.lower() == 'e':
        return -3.7 if token.isupper() else -6.4
    if s == 'エ' and tail.endswith(('クリ', 'ク')):
        return -5.0
    if s in {'cree', 'creo'}:
        return -2.0
    if s == 'ree':
        return -3.0 if p in {'c', '-c'} else -0.8
    # Vowel hiatus after co-, not arbitrary continuations like co-ast.
    if p == 'co':
        if s in {'e', 'ë', 'ö'}: return -3.4
        if s in {'en', 'on', 'om', 'or'}: return -1.7
    # The accented vowel in the Italian elision c'è / c’è.
    if tail.lower().endswith(("c'", 'c’')) and s == 'è':
        return -2.5
    # Thai มี (have), ดี (good), อี: the separate long-i vowel.
    if s == 'ี':
        if tail.endswith('ม'):
            return -4.3 if tail.endswith('ไม่ม') else -8.4
        if tail.endswith('ด'): return -3.1
        if tail.endswith('อ'): return -1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail, pending = 0, '', '', b''
    else:
        _, position, previous, tail, pending = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    joined = pending + raw
    decoded, used = codecs.utf_8_decode(joined, 'ignore', False)
    incomplete = joined[used:]
    value = chinese(decoded.strip(), tail)
    if pending and decoded and value:
        value *= 1.3
    # A separately arriving second byte can fire before the Han character
    # is complete. 姜 shares its prefix with 姐, 姨, 姑 and other 女 forms.
    if (len(pending) == 1 and len(incomplete) == 2
            and previous.startswith(' ')):
        if incomplete == GINGER:
            value = 6.0
        elif incomplete in ALLIUMS:
            value = 3.3
    if not value and token:
        value = spelling(token, previous, tail)
    if position == 0:
        value -= 0.12
        if token.startswith('//') and '\n' in token:
            value = -5.0
        elif token == '--':
            value = -2.24
    if position == 1 and previous == 'Title' and token == ':':
        value = 5.0
    tail = (tail + decoded)[-16:]
    return (doc, position + 1, token, tail, incomplete), value

"""An orthographic response, strongest on the Persian alef--yeh fragment.

Alef--yeh is boosted after heh (often the plural -hây), reduced after
بر (as in barây, "for"), and reduced after a zero-width separator.
Smaller rules cover Arabic alef/hamza-yeh, Persian yeh, Turkish soft g,
and vowel-following i-diaeresis. Array fragments are boosted in LaTeX
openings; double middle-dot tokens also receive a positive value.
At document openings the background is higher, especially for Latin words.
Uncovered text otherwise receives only a small background activation.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    opening = carry is None or carry[0] != doc
    before = '' if opening else carry[1]
    token = prefix.token_strings[-1]
    value = 0.002
    if opening:
        word = token.strip()
        value = 0.11
        if word.isascii() and word.isalpha():
            value = 0.13 if word.islower() else 0.17
        elif not word or word.isnumeric() or not any(c.isalnum() for c in word):
            value = 0.05

    if token == 'ای':
        value = 3.1
        if before.endswith('ه'):
            value = 3.55  # Persian plural -hây
            if before.endswith('\u200cه'):
                value = 3.17
        elif before.endswith('بر'):
            value = 2.15  # barây: "for"
        elif before.endswith('\u200c'):
            value = 1.4   # separated adjectival -i
    elif token == 'ائ':
        value = 1.07
    elif token == 'ی':
        value = 0.14
    elif token == 'ğ':
        value = 1.0 if before.endswith(('e', 'i')) else 0.5
    elif token == 'ï' and before[-1:].lower() in ('a', 'e', 'i', 'o', 'u'):
        value = 0.75
    elif token == 'array':
        value = 1.33 if before.endswith(('begin{', 'eqn')) else 0.17
    elif token == '··':
        value = 0.71

    return (doc, (before + token)[-24:]), value

"""A documentation-syntax detector, especially JSDoc's type declarations.

Opening type braces after @param, @return, or @type get large positive
pulses. Inline @var/@type declarations also get positive pulses. Other
rules approximate smaller documentation, import, and license delimiters.
A short text suffix is reset at document boundaries; other tokens get zero.
This deliberately leaves unrelated lexical responses unexplained.
"""
import re

READS = ()
TYPE_BRACES = {'param': 17.5, 'return': 12.8, 'returns': 11.2,
               'type': 13.2}
XML_DOC_TAGS = {'param': 2.1, 'summary': 1.4,
                'returns': 1.8, 'value': 1.5}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    # A single @, not the @@ delimiters of a source-code diff.
    at_sign = bool(re.search(r'(?<!@)@[ \t]*$', tail))
    tag = re.search(r'(?<!@)@([A-Za-z]+)[ \t]*$', tail)
    doc_tag = re.search(r'(?:\*|///)[ \t]*@([A-Za-z]*)[ \t]*$', tail)
    inline = bool(re.search(r'/\*\*[ \t]*@[ \t]*$', tail))

    if word in ('{', '{{', '{*}') and tag:
        value = TYPE_BRACES.get(tag[1].lower(), 0.0)
        if word == '{*}':
            value *= 0.27
        elif word == '{{':
            value *= 0.8
    elif word in ('var', 'type') and at_sign and doc_tag:
        value = (8.2 if inline else 5.3) if word == 'var' else 9.0
    elif word == 'param' and at_sign and doc_tag:
        value = 1.2 if inline else -0.6
        if re.search(r'///[ \t]*@[ \t]*$', tail):
            value = -1.8
    elif word == 'param' and tail.rstrip().endswith('\\'):
        value = -1.6
    elif word in ('return', 'returns') and at_sign:
        value = 1.3
    elif word == 'return' and tail.rstrip().endswith('\\'):
        value = 1.1
    elif word == ':' and doc_tag and doc_tag[1]:
        value = -5.2
    elif word == 'c' and at_sign:
        value = -5.5
    elif word == 'ref' and at_sign:
        value = -2.8
    elif word == 'brief' and tail.rstrip().endswith(('\\', '@')):
        value = -1.2
    elif word == '#' and re.search(r'@see[ \t]*$', tail):
        value = -2.8
    elif word == '@' and re.search(r'/\*\*[ \t]*$', tail):
        value = 2.9
    elif word == '{@':
        value = 1.2
    elif word == '\\' and tag and tag[1] in ('param', 'return'):
        value = 3.2 if tag[1] == 'param' else 2.1
    elif word == '$' and re.search(r'@param[ \t]+[^\r\n]*$', tail):
        value = 3.3 if tag else 1.1
    elif word in XML_DOC_TAGS and re.search(r'///[^\r\n]*<$', tail):
        value = XML_DOC_TAGS[word]
    elif word == 'name' and re.search(r'<param[ \t]*$', tail):
        value = 1.4
    elif word == '="' and re.search(r'<param[ \t]+name$', tail):
        value = -1.8
    elif word == '{' and re.search(r'\bimport[ \t]*$', tail):
        value = 1.6
    elif word == '{' and re.search(r'\b(?:const|let)[ \t]*$', tail):
        value = 0.25
    elif word == 'under' and re.search(r'\bLicensed[ \t]*$', tail):
        value = 1.0
    return (doc, (tail + token)[-240:]), value

programs.haiku:
"""Doc-comment tag detector: fires on the token that begins a tag's type slot.

In JSDoc/PHPDoc comments a tag is written "@param", "@return(s)", "@type", "@var" and
the type follows it. The component fires strongly on the opening brace of a JSDoc type
("@param {", "@returns {", "@type {") and on the tag words "@var" / "@type" themselves. It is
negative on the colon of a header-style tag ("@author:", "@date:", "@Since：").
"""

READS = ()

# JSDoc tags whose next token is a {type}, and how strongly the brace fires after each.
BRACE_AFTER = {"param": 17.0, "return": 12.0, "returns": 11.0, "type": 14.0, "throws": 10.0}
TAG_WORDS = {"var": 6.0, "type": 9.0}
COLONS = (":", "：")


def is_tag_at(raw):
    """A bare "@" token that starts a word, as in " @param" (not an email's "a@b")."""
    return raw.strip() == "@" and raw[:1] in (" ", "\t", "\n")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-3:]
    cur = raw[-1].strip()
    prev = raw[-2].strip() if len(raw) > 1 else ""
    if len(raw) > 2 and is_tag_at(raw[-3]):
        if cur in ("{", "{{") and prev in BRACE_AFTER:
            return carry, BRACE_AFTER[prev]
        if cur in COLONS:
            return carry, -5.0
    if len(raw) > 1 and is_tag_at(raw[-2]) and cur in TAG_WORDS:
        return carry, TAG_WORDS[cur]
    return carry, 0.0

programs.sol:
"""A small boundary-and-syntax approximation.

Most positions are close to zero. At a document's first token there is a
positive offset, weaker for Han text and negative for several code-opening
forms. Separate conspicuous responses cover title-label colons, URL scheme
separators, return keywords, middle-dot runs, nonbreaking spaces, and chat tags.
This does not explain the remaining token-specific variation.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')
CODE_OPENERS = {
    'using', 'package', 'namespace', 'const', 'var', 'let',
    'function', 'export',
}
C_DIRECTIVES = {'#include', '#define', '#ifndef', '#ifdef', '#pragma'}
