        return 0.0
    quote = m.group()
    suffix = s[m.end():]
    if quote == "'" and suffix in ('s', 't', 'm', 'd', 're', 've', 'll'):
        return 0.0  # Contractions are not opening strings.
    if re.search(r'''["'\n\r),;}]''', suffix):
