        return 1.7 if quote == '"' else 1.1
    if lead.endswith('=\\'):
        return -0.1  # Escaped HTML attribute quotes.
    if suffix.startswith('/'):
        return 0.45 if '(' in lead else 0.0
    if '(' in lead:
        if lead.startswith(' '):
            return 0.2  # A spaced parenthesis is often prose, not a call.
        return 0.6 if '\\' in lead else 0.85
