            return 2.0 if quote == '"' else 1.45
        if key == 'description':
            return 1.8
        if key == 'command':
            return 1.32
        return 0.85
    if prev == ',':
        if before.rfind('(') > before.rfind('{'):
            return 1.0  # Another string argument in a function call.
        # A quote after a quoted JSON value usually begins the next key.
        if quote == '"' and re.search(r'"\s*,$', before):
            return -0.1
        return 0.3 if lead.endswith(',') else 0.55
