"""layers.1.mlp.down_proj:1610: a feature for "a quoted string or a first-person clause starts here".

Plain-language summary of what this program predicts (activation units):
- The end-of-document token <|endoftext|>: about 1.2, its most consistent trigger.
- The subject pronoun "I" in English prose ("... when I have ...", "so I think"): about
  0.95; about 0.65 right after a period. Lowercase " i" is weak (0.25).
- The opening double quote of a value: after a colon, as in JSON or a dict ('"name": "'),
  about 1.5. After an operator or open paren ('print("', 'x + "') about 0.8. After a comma,
  or in prose, about 0.15. A quote that closes a string is about 0, except after a colon.
- The opening quote of a call argument, '("' or "('", about 0.9.
- Single-quoted strings follow the same pattern, a little lower.
- The word "Wait" (as in "Wait, actually"): about 0.7.
- The first token of a row: -0.25.
Everything else is 0. Quote parity is tracked per line, so opening and closing quotes can be told
apart without reading the future.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
WAIT = {"Wait", " Wait", " wait"}
CALL_OPEN = {'("', "('"}
OPERATORS = {"+", "<<", "=", "(", "return", "=>"}


def step(carry, prefix, upstream):
    # carry: (a double quote is open on this line, a single quote is open on this line)
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    dq, sq = (0, 0) if new_doc or carry is None else carry
    if len(prefix) == 1:
        value = -0.25
    elif tok == END_OF_TEXT:
        value = 1.2
    elif tok == " I":
        value = 0.65 if prev.endswith(".") else 0.95
    elif tok == "I":
        value = 0.7 if "\n" in prev else 0.2
    elif tok == " i":
        value = 0.25
    elif tok in WAIT:
        value = 0.7
    elif tok in CALL_OPEN:
        value = 0.9
    elif tok in (' "', '"') and dq == 0:
        value = 1.5 if prev.endswith(":") else 0.8 if prev.strip() in OPERATORS else 0.15
    elif tok in (' "', '"'):
        value = 0.9 if prev.endswith(":") else 0.0
    elif tok == ':"' and dq == 0:
        value = 1.2
    elif tok in (" '", "'") and sq == 0:
        value = 1.2 if prev.endswith(":") else 0.3
        if prev.strip() in OPERATORS:
            value = 0.8
        elif prev.endswith(","):
            value = 0.7
    else:
        value = 0.0
    if "\n" in tok:
        dq = sq = 0
    carry = ((dq + tok.count('"')) % 2, (sq + tok.count("'")) % 2)
