"""Sparse spelling and formatting responses.

In recent text with distinctive Baltic accents, short letter fragments
containing 'a' tend positive, especially word-initial pa-, ap- and at-.
Other short fragments tend slightly negative; final Lithuanian ų is more
negative.  HTML anchor names have a separate negative response, while the
colon of a document-opening Title: header is strongly positive.
Document-initial SQL or newline-terminated C++ comment markers are positive.

The accent check is only a local spelling heuristic, not a language model.
Numbers are rounded fits to training examples, not token-ID lookups.
"""
import re

READS = ()
BALTIC_ACCENTS = frozenset('ėįųģķļņ')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, count = '', 0
    else:
        _, history, count = carry
    token = prefix.token_strings[-1]
    recent = (history + token)[-128:]
    value = 0.0

    if token == ':' and history.endswith('Title') and count <= 2:
        value = 4.67
    elif token == 'a' and history.endswith('</'):
        value = -3.7
    elif token == 'a' and history.endswith('<'):
        value = -5.1
    elif token == '<a':
        value = -3.9
    elif count == 0 and token in ('--', '//\n'):
        value = 2.0
    elif BALTIC_ACCENTS.intersection(recent.lower()):
        word = token.strip().lower()
        if word.isalpha() and len(word) <= 5:
            initial = (token[0].isspace() or not history
                       or not history[-1].isalpha())
            has_a = 'a' in word or 'ā' in word
            value = -0.33 + 0.48 * initial + 0.78 * has_a
            if initial and has_a:
                value -= 0.11
            if initial and word.startswith('pa'):
                value += 3.84
            elif initial and word.startswith(('ap', 'at')):
                value += 2.57
            if word.endswith('ų'):
                value -= 1.0
            if 'ā' in word:
                value -= 0.55
            if has_a and not initial:
                match = re.search(r'[^\W\d_]+$', history)
                if match and match.group().lower() in ('p', 'pr'):
                    value += 0.92

    return (doc, recent, count + 1), value

