READS = ()
TAG_OPENERS = ('<', '</', '><')


def first_token_value(s):
    """Activation at a document's first token, from that token alone."""
    if s[:1] in ('#', '/') or s[:2] == '--':
        return 0.5
    if s[:1] == '\n':
        return -0.6
    if s[:1].isdigit():
        return -0.3
    if s[:2] == '<|':
        return -0.2
    if len(s) == 1 and s.isupper():
        return -0.5
    if s[:1].isalpha():
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, first_token_value(cur)
    prev = prefix.token_strings[-2]
    if cur == '<a':
        return None, -4.0
    if cur == 'a' and (prev.endswith(TAG_OPENERS) or prev.endswith('Act')):
        return None, -5.0
    if cur == 'A' and prev.endswith(TAG_OPENERS):
        return None, -2.0
    if cur == ':' and prev == 'Title' and (
        len(prefix) == 2 or prefix.document_ids[-3] != prefix.document_ids[-2]
    ):
