    token = prefix.token_strings[-1]
    text = (tail + prefix.token_bytes[-1]).decode('utf8', 'replace')
    match = re.search(r'[^\W\d_]+$', text)
    word = match.group(0) if match else ''
    letters = ''.join(c for c in roman(token) if c.isalpha())
    at = letters.find('en')
    size = len(letters)
    common = frequency(word) if at >= 0 or letters.startswith('n') else 0.0
    previous_size = len(roman(previous).strip())
    value = 0.0

    if 0 <= at <= 1:
        if size <= 3:
            if common >= 4.8:
                value = -0.1
            elif at == 0:
                value = -0.95 if previous_size <= 4 else -0.4
                if token[:1].isspace():
                    value = -0.55
            else:
                value = -0.55 if len(token) > 1 else -0.1
        elif size == 4:
            value = -0.35 if token.isascii() and common < 4.1 else -0.08
        elif len(word) > 4 and len(token) > 3:
            value = -0.1
    elif 2 <= at <= 4:
        value = -0.15 if size <= 5 and len(word) > 4 else -0.05
    else:
        # Join the last written E to a new N, not unrelated adjacent words.
        old_text = tail.decode('utf8', 'replace').rstrip()
        last = roman(old_text[-1:])[-1:]
        joined = (not token[:1].isspace() or len(previous.strip()) == 1)
        if last == 'e' and letters.startswith('n') and joined and size <= 3:
