        return -0.25 if word in ('public', 'static') or not word else 0.05
    if s.strip() == 'fn':
        return -1.9 if re.search(r'#\[test\][^{};]{0,40}$', before) else -0.06
    if s == ' (' and word == 'func':
        return 1.3
    if s == ',' and re.search(r'TEST_[FP]\([^,\n]{1,80}$', before):
        return -2.8
    if s == ' __' and word in ('def', 'function'):
        return 0.8
    if s == ':' and before == 'Title':
        return -2.56
    if s == 'summary' and before.endswith(('<', '</')):
        return 0.65
    if s in ('.List', '.Map') and before.endswith('.util'):
        return 1.7
    if s == 'usr' and before.endswith('/'):
        return 0.6 if before.endswith('#!/') else -0.95
    if s == '/bin':
        return -0.45
    if s == '/env' and before.endswith('/bin'):
        return 2.0
    if s == '··':
        return -0.875 if start or before.endswith('··') else 0.0
    if start:
        if s == '//\n':
            return 9.75
        if s in ('package', 'import'):
            return -1.16
    if s == '\r' and (start or not before.strip('\r')):
        return 4.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = response(s, before, not before)
    return (doc, (before + s)[-160:]), value

"""Written quantities, conditioned on nearby language and number syntax.

East Asian numerals and several quantity/determiner words have negative
responses. ASCII digits inherit a local script context and a stronger
negative response after year/month markers or articles. Completing 19xx/20xx
adds a year-ending response. Uses 64 recent decoded characters; resets at
document boundaries. Sparse code-formatting responses are not reproduced.
"""
import re
import unicodedata as ud
import regex
from atoms import FULLWIDTH_DIGITS

READS = ()
ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]')
NONLATIN = regex.compile(r'[^\p{Latin}\p{Common}\p{Inherited}]')
# Many/few, several, each, half, and the counting form of two.
QUANTIFIERS = {'多', '少', '几', '幾', '数', '數', '各', '每', '半', '兩', '两'}
# This/that and which/what.
DETERMINERS = {'这', '這', '那', '哪', '何'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw, first = b'', True
    else:
        raw, first = carry[1], False
    before = raw.decode('utf-8', errors='ignore')[-64:]
    s = prefix.token_strings[-1]
    u = s.strip()
    digit = bool(u) and u.isascii() and u.isdigit()
    value = 0.16 if first else 0.0

    if digit or s == ' ':
        base = re.sub(r'[0-9]+$', '', before)
        word = re.search(r'([A-Za-z]+)\s+$', base)
        article = word[1].lower() if word else ''
        marker = base.rstrip()[-1:]
        korean = bool(regex.search(r'\p{Hangul}', before[-32:]))
        value -= 0.71 * korean
        if marker and marker in '年月년월':
            value -= 1.1
        if digit:
            recent = len(ASIAN.findall(before[-24:])) / 24
            near = len(ASIAN.findall(before[-4:])) / 4
            value -= 0.40 * recent + 0.82 * near
            value -= 0.65 * bool(ASIAN.fullmatch(before[-1:]))
            value -= 0.17 * len(NONLATIN.findall(before[-24:])) / 24
            n = len(before) - len(base) + len(u)
            if n > 1:
                value -= 0.38 * recent
                if ASIAN.fullmatch(base[-1:]):
                    value -= 0.54 / n**0.5
            if article in ('a', 'an'):
                value -= 0.60 if article == 'a' else 0.75
            if n == len(u) and re.search(r'\bthe\s+$', before, re.I):
                value -= 0.29
            run = before[len(base):] + u
            if len(run) == 4 and run.startswith(('19', '20')):
                value += 0.265 if run.startswith('19') else 0.53
                value += -0.49 * recent + 0.06 * near + 0.22 * korean
        else:
            word = re.search(r'([A-Za-z]+)\s*$', before)
            if word and word[1].lower() in ('a', 'an'):
                value -= 0.68
    elif u:
        numeric = all(ud.numeric(c, None) is not None for c in u)
        if all(c in FULLWIDTH_DIGITS for c in u):
            value -= 1.7
        elif numeric and ASIAN.search(u):
            value -= 0.54
            if any(1 < ud.numeric(c, 0) < 10 for c in u):
                value -= 0.75
        if u.startswith('第') and any(ud.numeric(c, None) is not None for c in u):
            value -= 0.47
        if u.endswith('一') and len(u) > 1 and not u.startswith('第'):
            value -= 0.44
        if u in QUANTIFIERS:
            value -= 0.60
        if u in DETERMINERS:
            value -= 0.95
        if u in ('几', '幾'):
            value -= 1.14
        if u == '每':
            value -= 0.79
    raw = (raw + prefix.token_bytes[-1])[-256:]
    return (doc, raw), float(value)

"""A sparse recognizer for web links and source-code boilerplate.

The largest positive pulse is the /wiki path in Wikipedia links. Smaller
pulses mark some familiar import, filename, HTML and forum conventions;
Wikipedia's domain ending and 'using namespace' have negative pulses.
Keep a short text tail and remember ArrayList imports within each document.
Unrecognized positions are approximated by zero, not by a token lookup table.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, array_list = "", False
    else:
        _, tail, array_list = carry
    token = prefix.token_strings[-1]
    previous = tail.rstrip()
    value = 0.0

    # Encyclopedias and question/discussion URLs.
    if token == "/wiki":
        value = 17.3
    elif token in ("wiki", " wiki"):
        value = 6.0 if previous.endswith(("community", "://")) else 2.4
    elif token == ".org" and previous.endswith("wikipedia"):
        value = -4.3
    elif token == "/questions" and previous.endswith(
        ("stackexchange.com", "stackoverflow.com")
    ):
        value = 6.2
    elif token == "/comments" and "reddit.com/r/" in tail[-120:]:
        value = 7.8
    elif token == "?q" and previous.endswith("/search"):
        value = 3.0

    # Recurrent source-code phrases.
    elif token == " namespace" and previous.endswith("using"):
        value = -5.4
    elif token == "namespace" and not previous.endswith("<?php"):
        value = -0.7
    elif token == ".List" and previous.endswith("java.util") and array_list:
        value = 6.0
    elif token == ".Slf" and previous.endswith("lombok.extern.slf4j"):
        value = 4.9
    elif token == ".annotation":
        if previous.endswith("java.lang"):
            value = 4.5
        elif re.search(r"import [\w.]+$", previous):
            value = 2.5
    elif token == "l" and previous.endswith(("tom", "Tom")):
        value = 5.8 if previous.endswith(".tom") else 3.2
    elif token == "/env" and previous.endswith("/usr/bin"):
        value = 1.22
    elif token == " python" and previous.endswith("/usr/bin/env"):
        value = -1.73
    elif token == "php" and previous.endswith("<?"):
        value = 2.02
    elif token == " name":
        if previous.endswith("<param"):
            value = 1.5
        elif previous.endswith("<a"):
            value = 5.5

    # Documentation hosts and anonymized email addresses.
    elif token == ".org" and previous.endswith("docs.python"):
        value = 3.4
    elif token == ".com":
        if previous.endswith("email@example"):
            value = 0.85
        elif re.search(r'(?:https?://)docs\.[\w.]+$', previous):
            value = 2.8
        elif previous.endswith("https://cloud.google"):
            value = 4.0
        elif re.search(r'(?:https?://)developers\.[\w.]+$', previous):
            value = 6.5
        elif re.search(r'(?:https?://)learn\.[\w.]+$', previous):
            value = 7.0

    # Small, stereotyped web-page labels.
    elif token == " views" and re.search(r'\n\d+[kKmM]?$', previous):
        value = 1.2
    elif token == " Level" and previous.endswith("Challenge"):
        value = 0.78
    elif token == " sites" and previous.endswith("Share on other"):
        value = 1.7
    elif token == " Posts" and re.search(r"(?:Joined:|Join Date:)", tail[-100:]):
        value = 1.2
    elif token == " reply" and previous.endswith("Latest"):
        value = 2.7
    elif token == " Discussion" and previous.endswith("Watch This"):
        value = 2.7
    elif token == " discussion" and previous.endswith("join the"):
        value = 1.7
    elif token.lower() == " homework":
        if previous.lower().endswith("math"):
            value = -2.4
        elif previous.endswith("Ask a"):
            value = -2.2
        elif previous.endswith("assignment"):
            value = 1.6
    elif token == " question" and previous.endswith("homework"):
        value = -1.7
    elif token == " Solver" and previous.endswith("Math"):
        value = -4.0
    elif token in (" more", " More") and previous.endswith("View"):
        value = -1.3
    elif token == " refs" and previous.endswith("graph;"):
        value = 5.45
    elif token == ":\n\n" and previous == "Q":
        value = 0.375
    elif token == "··" and not tail.strip("·"):
        value = -2.56

    tail = (tail + token)[-600:]
    array_list = array_list or "java.util.ArrayList" in tail
    return (doc, tail, array_list), value

"""Local linking constructions, usually from two tokens, occasionally three.

Demonstrative/relative pronoun + copula, partitives, and discourse connectives
are positive; coordinator + auxiliary and some locative idioms are negative.
Capitalization changes the strength. Three-word rules boost 'and that is'
and exempt 'keep in mind' from the negative 'in mind' rule. Unrecognized
positions get zero. These are phrase heuristics, not a general parser.
No context crosses a document boundary.
"""
READS = ()

COPULAS = {'is', 'are', 'was', 'were', 'am'}
COORDINATORS = {'and', 'but', 'or', 'nor'}
AUXILIARIES = set(
    'be have had will would can could should must do does did'.split())
QUANTIFIERS = set('some many any both either neither none several'.split())
LINK_ADVERBS = set('also so thus rather yet therefore still hence'.split())
PRE_COPULA_ADVERBS = set(
    'also really often usually only therefore still clearly certainly probably'.split())
# Adverbial scope and locative expressions beginning with 'in'.
AFTER_IN = {
    'general': 1.3, 'particular': 1.1, 'contrast': 1.4, 'part': 2.6,
    'detail': 0.8, 'short': 1.7, 'practice': 1.1, 'turn': 0.4,
    'two': 0.8, 'comparison': 0.9, 'series': -1.6, 'view': -2.1,
    'place': -3.9, 'front': -1.9,
}
FOCUS_ADVERBS = {
    'mainly': 1.3, 'mostly': 1.3, 'chiefly': 1.8, 'partly': 1.6,
    'primarily': 0.7, 'ultimately': 1.5, 'importantly': 2.7,
    'firstly': 2.8, 'secondly': 3.2, 'lastly': 2.0,
}
SENTENCE_CONNECTIVES = {
    'First': 1.7, 'Second': 1.5, 'Firstly': 2.7, 'Secondly': 3.5,
    'Ultimately': 2.5, 'Overall': 1.7, 'Generally': 0.8,
    'Thus': 0.4, 'Further': 0.7, 'Moreover': 0.4,
}
# Short conventional phrases, rather than unrestricted word associations.
IDIOMS = {
    'other words': 1.0, 'other hand': 1.0,
    'once again': 1.1, 'then again': 1.1, 'of them': 0.45,
    'not have': -0.75, "'t have": -0.75, '’t have': -0.75,
    'not only': 0.5, 'at all': 0.65, 'to mind': -3.5,
    'of mind': -2.5, 'of place': -3.5,
    'either case': 1.6, 'either way': 1.6, 'than usual': -1.7,
    'especially as': -3.2, 'except as': -3.2, 'such as': 0.3,
}


def predict(previous, current, before=''):
    p = previous.strip().lstrip('>"\'(')
    a, w = p.lower(), current.strip()
    b, prior = w.lower(), before.strip().lower()
    capital, spaced = p[:1].isupper(), previous.startswith(' ')
    if current.startswith(' '):
        if b in COPULAS:
            if a in COORDINATORS and (spaced or capital):
                v = {'is': -3.7, 'are': -3.1, 'was': -2.8,
                     'were': -2.5, 'am': -2.2}
                value = v[b]
                value *= 0.87 if a != 'and' else 1
                value *= 0.65 if capital else 1
                return value * (0.65 if w.isupper() else 1)
            if a in {'as', 'than'} and spaced:
                return -3.5 if b in {'is', 'are'} else -2.5
            if a in PRE_COPULA_ADVERBS:
                return -2.1
            if a in {'this', 'that', 'which'}:
                if b == 'was':
                    return (2.7 if a == 'that' else 1.5) if capital else 0.7
                if b == 'is':
                    if capital:
                        return {'this': 2.5, 'that': 4.6, 'which': 2.2}[a]
                    if a == 'that':
                        if prior in COORDINATORS:
                            return 3.4 if prior == 'and' else 2.8
                        if prior in {',', ';', '--', 'if', 'so', 'since',
                                     'because', 'unless', 'whether'}:
                            return 2.4
                        return 0.6 if spaced else 2.0
                    return 1.4 if a == 'this' else 0.9
            if a in {'these', 'those'} and b in {'are', 'were'}:
                return 1.6 if capital else 0.7
            if a == 'you' and b == 'are' and spaced and not capital:
                return -0.3
            if p == ',':
                return -0.3
            if a == 'there':
                return 0.1
        if a in COORDINATORS and spaced:
            if b == 'has' or b in AUXILIARIES or b in {'as', 'which'}:
                return -1.7 if b == 'has' else -1.0
            if b in LINK_ADVERBS:
                return 1.9 if a == 'but' else (0.75 if b == 'also' else 1.4)
        if b == 'of':
            if a in {'most', 'first', 'all'}:
                return {'most': 3.4 if capital else 2.2,
                        'first': 4.1 if capital else 0.0, 'all': 0.35}[a]
            if a in QUANTIFIERS:
                return 1.4 if capital else 0.85
        if a == 'in':
            if b == 'mind':
                return 0.2 if prior in {'keep', 'keeping', 'kept'} else -3.7
            if capital:
                initial = {'short': 4.2, 'part': 3.2, 'addition': 0.7,
                           'general': 1.8, 'case': 1.0,
                           'cases': 2.0, 'practice': 2.0}
                if b in initial:
                    return initial[b]
            if b in AFTER_IN:
                return AFTER_IN[b]
        if b in FOCUS_ADVERBS:
            v = FOCUS_ADVERBS[b]
            if p in {',', ':', ';', '-', '–', '—'} or a in COORDINATORS:
                v += 0.8
            return v + (1.5 if a in {'most', 'more'} and b == 'importantly' else 0)
        if a == 'of' and b == 'all' and prior in {'first', 'most'}:
            return 4.1
        if a in {'some', 'many', 'both'} and b == 'cases':
            return 2.1
        if a in {'a', 'the'} and b == 'sense' and prior == 'in':
            return 2.8
        if b == 'be' and a in {'may', 'might', 'could', 'would', 'will'}:
            return 1.5 if prior in {'this', 'that'} else 0.15
        if a == 'if' and b in {'so', 'yes'}:
            return 2.2 if capital else 3.1
        if a in {'в', 'о', 'на'} and b in {'том', 'то'}:
            return {'в': 4.5, 'о': 2.4, 'на': 5.0}[a] + (0.7 if capital else 0)
        phrase = a + ' ' + b
        if phrase in IDIOMS:
            return IDIOMS[phrase]
    if w in SENTENCE_CONNECTIVES:
        if p.endswith(('.', '!', '?')) or '\n' in previous or not previous:
            if w == 'First' and not current.startswith(' '):
                return 0.8
            return SENTENCE_CONNECTIVES[w]
    if b in {"'s", '’s'} and a in {'this', 'that'}:
        return 2.5 if capital else 1.4
    if a == 'as' and b == '-is':
        return -3.5
    if b == 'ly' and a in {'first', 'second', 'main', 'chief'}:
        return 4.1 if capital else 2.8
    if a == 'import' and b == 'antly':
        return 4.6 if capital else 2.8
    if a == 'not' and b == 'ably' and capital:
        return 3.0
    return 0.0


def step(carry, prefix, upstream):
    t, docs = prefix.position, prefix.document_ids
    previous = prefix.token_strings[-2] if t and docs[-1] == docs[-2] else ''
    before = prefix.token_strings[-3] if t > 1 and docs[-1] == docs[-3] else ''
    return None, float(predict(previous, prefix.token_strings[-1], before))

programs.haiku:
"""Layer-1 MLP neuron 1627 (the down_proj component), read from its own words.

What it does: a predicate-or-connective detector. Its activation is negative when a
finite verb or auxiliary follows a conjunction with its subject left out ("and is",
"or are", "but was", strongest; "and has", "and will", weaker), on "as is", and on
"in place", "in front", "in view", "in mind", "out of mind".

It is positive on a connective that starts a clause after a conjunction ("and so",
"but also", "and thus", "and hence"); on a demonstrative starting a copula ("That is"
strongest, then "This is", "Which is", "These are"); on "is" after "which" or "that";
on "most of" and "some of"; on "In short", "in part", "in particular", "in general";
on a discourse signpost opening a sentence ("Secondly", "Firstly", "Importantly",
"Overall"); and on Russian "то" after a preposition ("в то, что").

Values are the mean activations in the training sample, rounded. Everything else is 0.
"""

READS = ()

CONJUNCTIONS = {"and", "or", "but", "nor", "as", "also", "really", "not"}
SENTENCE_STARTS = {"", ".", "!", "?", ":", "\n"}
COPULAS = {"is", "are", "was", "were", "am", "IS", "'s", "’s"}
AUX_VERBS = {"has", "have", "had", "will", "would", "should", "could", "can"}
LINKERS = {"so", "thus", "also", "therefore", "hence", "rather", "consequently", "still",
           "instead", "actually", "further", "eventually", "partly", "especially", "overall",
           "first", "second", "third"}
STRONG_SIGNPOSTS = {"Firstly", "Secondly", "Thirdly", "Ultimately", "Importantly", "importantly",
                    "Mainly", "mainly"}
WEAK_SIGNPOSTS = {"First", "Second", "Third", "Overall", "Plus", "Generally", "Moreover", "Hence",
                  "Consequently", "Further", "Furthermore", "Typically", "Usually", "Specifically",
                  "Basically"}
DEMONSTRATIVES = {"This", "These", "That", "Which"}
RELATIVES = {"which", "that", "this"}
QUANTIFIERS = {"most", "Most", "some", "any", "none", "both", "best", "First"}
IN_PHRASES = {"short": 3.0, "part": 2.4, "particular": 1.2, "general": 1.5, "contrast": 1.4,
              "summary": 1.1, "conclusion": 1.1, "addition": 0.6}
IN_IDIOMS = {"place": -3.5, "front": -2.0, "view": -2.3, "mind": -1.7}
RUSSIAN_LINKERS = {"в", "В", "на", "о", "и", "И", "А", "а", "у", "У"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if prev in CONJUNCTIONS:
        if word in COPULAS:
            return carry, -3.3
        if word in AUX_VERBS:
            return carry, -1.0
        if word in LINKERS:
            return carry, 1.5
    if word in COPULAS and prev == "That":
        return carry, 4.5 if word == "is" else 2.4
    if word in COPULAS and prev in DEMONSTRATIVES:
        return carry, 1.5 if word in {"was", "were"} else 2.5
    if word in {"is", "'s", "’s"} and prev in RELATIVES:
        return carry, 1.0
    if word == "of" and prev in QUANTIFIERS:
        return carry, 2.0 if prev in {"most", "Most", "First"} else 1.0
    if prev == "In" and word in IN_PHRASES:
        return carry, IN_PHRASES[word]
    if prev == "in" and word in IN_IDIOMS:
        return carry, IN_IDIOMS[word]
    if word == "mind" and prev in {"to", "of"}:
        return carry, -2.5
    if prev in SENTENCE_STARTS and word in STRONG_SIGNPOSTS:
        return carry, 3.0
    if prev in SENTENCE_STARTS and word in WEAK_SIGNPOSTS:
        return carry, 1.0
    if word in {"то", "том"} and prev in RUSSIAN_LINKERS:
        return carry, 3.0
    return carry, 0.0

programs.sol:
"""A document-opening code/header detector, not a general code detector.

The largest spikes are on the first token of a document: an empty // comment,
a Python definition, or an HTML declaration. Smaller rules cover other code
headers and a few opening-token formatting classes. There is also a weak
positive offset for semicolon terminators. Most lexical variation is omitted.
"""
READS = ()

FILE_OPENERS = {
    '//\n': 2.82,
    '//\r\n': 1.22,
    'def': 1.58,
    '<!': 2.33,
    'export': 1.04,
}
HEADER_STARTS = {'#', '##', '#include', '"""', '"""\n', "'''"}
DECLARATION_STARTS = {
    'class', 'package', 'public', 'private', 'const', 'from', 'func',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    value = 0.05 if token.lstrip().startswith(';') else 0.002
    if first:
        value = FILE_OPENERS.get(token, 0.002)
        if token in HEADER_STARTS:
            value = 0.60
        elif token in DECLARATION_STARTS or token in {'//', '/*', '/**'}:
            value = 0.43
        elif token in {'<|im_start|>', '<|im_end|>'}:
            value = -0.24
        elif token == '<|endoftext|>':
            value = 0.85
        elif token in {'The', 'A', 'An'}:
            value = 0.43
        elif token.isascii() and token.isdigit():
            value = 0.10
        elif token in {'\t', '\r\n'}:
            value = 0.49
        elif token and all(ch == '\n' for ch in token):
            value = 0.27 / len(token)
    elif carry[1] and token == '//':
        value = 0.204
    return (document, first and token == '//\n'), value

"""Approximate a spelling feature centered on ft and German/Dutch cht.

Short fragments and clusters split before t get negative values. Long or common
word forms are weaker; -raft/-rift/-roft endings and especially graft are stronger.
Only a short inflectional suffix inherits the preceding response. Analogous
Cyrillic, Persian and Japanese spellings are included. Split f+ed/eld/eder and
repeated middle dots get small positive values. These are coarse spelling rules,
not a complete account of the component's lexical/contextual variation.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
TRANSLATION = str.maketrans({
    'ф': 'f', 'т': 't', 'ч': 'ch', 'х': 'h', 'ш': 'sh',
    'е': 'e', 'д': 'd',
    'ف': 'f', 'ت': 't', 'خ': 'h', 'ش': 'sh',
})
# English function words are not short suffix fragments.
FUNCTION_WORDS = frozenset({
    'to', 'too', 'the', 'this', 'that', 'these', 'those',
    'them', 'they', 'than', 'then',
})
CLUSTER = re.compile(r'ft|cht|(?<!g)ht')


@lru_cache(maxsize=4096)
def internal_response(text):
    token = text.lower().translate(TRANSLATION)
    if '<|' in token or 'http' in token or 'html' in token:
        return 0.0
    match = CLUSTER.search(token)
    if not match:
        return 0.0
    word = token.strip()
    space = token[0].isspace()
    before = len(token[:match.start()].strip())
    cluster = match.group()
    after = len(token) - match.end()
    if before >= 5:
        return 0.0
    if token.endswith('fty'):
        return 0.0
    if after >= 3:
        return -0.15 if cluster == 'ft' else 0.0
