"""Layer-1 MLP down-projection component 1635: the comparison-after-negation feature.

It fires on the word that opens a comparison in a negated clause, most of all the
"as" of "not as ... as" ("may not be as big as", "isn't as easy as"). The closer
the negation ("not" / "n't" / "never"), the stronger: about 4.5 right after it,
about 2 two words later, under 1 beyond that. It is also weaker on "be as",
"quite as", "not exactly", "not like", "not so", "not very". The same idea in
Chinese: 像 and 如 meaning "be like / as", strong after a negation or a modal
(不会像, 能像, 依然如, 不如), and slightly negative in "such as" lists (，如 CRC).
Everywhere else it is about zero. Values are typical activations, read off the
training data, not fitted per token.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

NEGATORS = {"not", "n't", "'t", "’t", "never", "nor", "nicht", "không", "不", "没", "没有"}
# "as" this many words after a negator -> typical activation
AS_BY_DISTANCE = {1: 4.5, 2: 2.0, 3: 0.9, 4: 0.7}
# a word right after a negator -> typical activation of the word that follows
AFTER_NOT = {"exactly": 2.5, "like": 2.5, "so": 1.1, "very": 0.9, "many": 1.2}
# "as" after these words (no negation) -> typical activation
AS_AFTER = {"be": 2.1, "been": 2.4, "quite": 3.1, "nearly": 2.6, "twice": 1.0, "or": 1.1,
            "exactly": 1.6, "just": 0.7, "do": 1.7, "go": 1.4, "than": 1.4, "being": 1.2,
            "is": 0.5, "are": 0.5, "was": 0.6, "good": 0.6, "feel": 0.9, "much": 0.3}
# Chinese comparison words, on their own
CHINESE = {"不如": 8.0, "不像": 5.6, "正如": 2.8, "不及": 2.1, "就像": 1.4, "像是": 1.6,
           "怎样": 1.0, "如此": 0.9, "如何": 0.4}
# words before 像 or 如 that make it a negated or modal "be like" (strong)
LIKE_CONTEXT = {"不", "没", "不会", "不能", "没有", "没能", "并不", "能", "会", "都", "也要", "要",
                "想", "正", "更", "依然", "就", "亦", "犹", "坚", "初"}
PUNCT = {"，", "。", "（", ","}


def step(carry, prefix, upstream: Mapping):
    docs, toks = prefix.document_ids, prefix.token_strings

    def back(k):
        # the word k tokens back, if it is in the same document
        if len(toks) > k and docs[-1 - k] == docs[-1]:
            return toks[-1 - k].strip()
        return ""

    cur, p1, p2 = back(0), back(1), back(2)
    if cur in CHINESE:
        return carry, CHINESE[cur]
    if cur == "像":
        return carry, 5.0 if p1 in LIKE_CONTEXT else 1.0
    if cur == "如":
        if p1 in LIKE_CONTEXT:
            return carry, 3.0
        return carry, -0.5 if p1 in PUNCT else 0.0
    if cur == "as":
        if p1 in ("be", "been", "being") and p2 in NEGATORS:
            return carry, 4.5
        for k in range(1, 5):
            if back(k) in NEGATORS:
                return carry, AS_BY_DISTANCE[k]
        return carry, AS_AFTER.get(p1, 0.0)
    if cur in AFTER_NOT and p1 in NEGATORS:
        return carry, AFTER_NOT[cur]
    if cur == "{" and p1 in ("import", "type"):
        return carry, 1.0
    return carry, 0.0

