    r'\b(check(?:s|ed|ing)?|see|seeing|sure|unsure|know|knowing|knows|'
    r'wonder(?:s|ed|ing)?|determin(?:e|ed|ing)|test(?:s|ed|ing)?|'
    r'verify|ask(?:s|ed|ing)?|tell|unclear|clear|uncertain|'
    r'doubt(?:s|ed|ing)?|decide|detect|confirm|examine|evaluate|understand|'
    r'establish|investigate|consider|indicate|ascertain|discuss(?:ing)?)(?: +\w+){0,2} *$')


