The colon immediately after an opening Title gets a large positive value.
Elsewhere, use a negative average for initial tokens containing letters or
only whitespace, and for temporal adverbs immediately after auxiliary have.
These small rules do not reproduce the remaining token-specific variation.
"""
READS = ()
HAVE = {'have', 'has', 'had', "'ve", '’ve'}
TEMPORAL_ADVERBS = {'always', 'never', 'ever', 'just'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry

    value = 0.0
    if position == 0 and (token.isspace() or any(c.isalpha() for c in token)):
        value = -0.17
    if position == 1 and previous == 'Title' and token == ':':
        value = 19.82
    elif (
        previous.strip().lower() in HAVE
        and token.strip().lower() in TEMPORAL_ADVERBS
    ):
        value = -0.55
    return (doc, position + 1, token), value

