TITLE_COLON = 19.7
FIRST_TOKEN = -0.14
HEADING_START = 0.65
HEADING_TOKENS = {"#", "##"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        offset, prev = 0, None
    else:
        offset, prev = carry[0] + 1, carry[1]
    if offset == 1 and prev == "Title" and tok == ":":
        value = TITLE_COLON
    elif offset == 0:
        value = HEADING_START if tok in HEADING_TOKENS else FIRST_TOKEN
    else:
