"""A sparse Hungarian-fragment and document-opening approximation.

For 80 tokens after a Hungarian cue, short Latin fragments get a spelling
score: back vowels raise it, while short i-endings and verb particles lower
it. Completing adjectival -ási/-ési or infinitive -ni is strongly negative.
A few document-opening and punctuation patterns have separate responses.
This omits most lexical variation, including the isolated Han responses.
"""
READS = ()

HUNGARIAN_CUES = {'hogy', 'egy', 'vagy'}
PARTICLES = {'meg', 'el', 'le', 'fel', 'ki', 'be'}
CODE_OPENERS = {'import', 'from', 'package', '#include', 'class'}


def count(text, letters):
    return sum(text.count(c) for c in letters)


def fragment_score(token, previous):
    s = token.strip().lower()
    if s == 'ú':
        return 2.5
    if not s.isascii() or not s.isalpha() or len(s) > 4:
        return 0.
    boundary = token[0].isspace() or not previous or not previous[-1].isalpha()
    if not boundary and s == 'i' and previous.endswith(('ás', 'és')):
        return -8.
    if not boundary and s == 'si' and previous.endswith(('á', 'é')):
        return -5.5
    if s.endswith('ni'):
        return -4.8
    if s == 'be' or (boundary and s in PARTICLES):
        return -6.5 if s == 'ki' else -3.5

    # A small spelling contrast, not a table of Hungarian words.
    value = .45 + .70 * count(s, 'aou') - .97 * s.count('i')
    value -= .40 * count(s, 'bcdfghjklmnpqrstvwxyz')
    value += .53 * s.count('r') - .19 * s.count('l')
    value += .80 * s.count('j') + .27 * count(s, 'ptk')
    value += .18 * count(s, 'bdg') + .23 * count(s, 'sz')
    value += .37 * token[0].isspace() - .15 * (len(s) == 1)
