        hungarian_left = 80
    value = fragment_score(token, previous) if hungarian_left else 0.
    if token == '://':
        value = -.34
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -.38

    if position == 1 and previous == 'Title' and token == ':':
        value = 4.64
    elif position == 0:
        if token.startswith('//') and '\n' in token:
            value = 2.23
        elif token in CODE_OPENERS:
            value = .9
        elif token == 'use':
            value = 2.36
        elif token == 'private':
            value = 1.86
        elif token == 'No':
            value = 1.8
        elif token == '**':
            value = -1.98
    return (doc, position + 1, token, hungarian_left), float(value)

