    if not word.isascii():
        return -9.4
    frequency = zipf_frequency(word, 'en')
    value = -8.3 - 0.35 * min(len(word), 16) + 0.33 * (frequency - 4)
    if 'noun.possession' in wordnet.categories(word):
        value -= 3.7
    if wordnet.is_a(word, 'organization'):
        value -= 3.7
    if wordnet.is_a(word, 'commerce'):
