    (r'ext', 2.8),
    (r'x', 0.6),
    (r'(?:ik|ikh|ice|ices|ick|icks|ek|eg)', 1.1),
    (r'(?:ide|ides|rex|uce|urtle)', 2.6),
    (r'[iu]x', 1.7),
    (r'il(?:e|es|ing)', 0.5),
    (r'(?:ind|ong|olls?)', -1.7),
    (r'(?:iv|ub|ı)', -0.6),
