import re

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name[1:], *calendar.month_abbr[1:])}
TIME_PREPOSITIONS = {'in', 'since', 'from', 'until', 'during', 'between', 'born'}


def year_level(lead, pair):
    words = re.findall(r'[a-z]+', lead.lower())
    word = words[-1] if words else ''
    last = lead[-1:]
    score = 0.65 + 0.18 * (pair == '19')
    if last == ' ':
        score += 0.08
    elif last == '(':
        score += 0.35
    elif last.isalpha():
        score += 0.28
    elif last == '/':
        score += 0.13
    elif last in (':', '"', "'"):
        score -= 0.18
    elif last in ('.', '-', '–', '—'):
        score -= 0.08
    if word in TIME_PREPOSITIONS:
        score += 0.39 + 0.15 * (word == 'in')
    if word in {'year', 'years', 'date', 'dated', 'published'}:
        score += 0.35
    if word in {'of', 'to'}:
        score -= 0.10
    if re.search(r'et\s+al\.?\s*[,()]?\s*$', lead, re.I):
        score += 0.72
    if any(w in MONTHS for w in words[-5:]):
        score += 0.36
    if '©' in lead[-45:] or 'copyright' in lead[-45:].lower():
        score += 0.60
    if any(c in lead[-45:] for c in '{}_=\\'):
        score -= 0.26
    if any(c in lead[-12:] for c in '=+^<>'):
        score -= 0.27
    if any(c in lead[-12:] for c in '$€£¥'):
        score -= 0.38
    if any(c.isdigit() for c in lead[-12:]):
        score -= 0.24
    return max(0.0, min(1.85, score))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, digits, history, lead, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '<|endoftext|>' and position == 0:
        value = -6.73
    elif token == '://' and history.endswith(('http', 'https')):
        value = 1.5 if history.endswith('https') else 1.3
    if token.isdecimal():
        if not digits:
            lead = history
        if (digits, token) in (('1', '9'), ('2', '0')):
            value = year_level(lead, digits + token)
        digits = (digits + token)[-12:]
    else:
        digits = ''
    history = (history + token)[-120:]
    return (doc, digits, history, lead, position + 1), value

"""A lexical approximation of two activation families.

Goods/works vocabulary (品, Korean 품, Vietnamese phẩm, and compounds)
gets positive values; byte-split completions are stronger. Selected English
'of' collocations get negative values, particularly negative partitives,
demands, and material-making predicates. A weaker -ed suffix heuristic covers
other past-participle-like heads. Unmatched tokens and 'of' contexts get zero.
Only a short preceding text tail is kept, reset at document boundaries.
"""
import re

READS = ()

# Partitive quantifiers: absence is much stronger than ordinary quantity.
QUANTIFIERS = {
    'none': -4.65, 'nothing': -2.45, 'neither': -2.15, 'nor': -2.4,
    'little': -1.65, 'much': -0.65, 'either': -0.6, 'any': -0.37,
    'some': -0.18, 'both': -0.15,
}


def of_complement(word, before):
    if word in QUANTIFIERS:
        return QUANTIFIERS[word]
    if word in {'required', 'expected', 'asked'}:
        return -9.2
    if word == 'born':
        return -8.3
    if word == 'true':
        return -5.0
    if word == 'built':
        return -6.0
    if word in {'constructed', 'manufactured', 'crafted'}:
        return -4.5
    if word in {'entirely', 'wholly', 'purely', 'solely', 'fully'}:
        return -2.7
    if word == 'made':
        return -2.6
    if word == 'prob':              # abbreviation for probability
        return -3.0
    if word in {'proud', 'ignorant', 'died'}:
        return -2.3
    if word in {'independent', 'independently', 'composed', 'disposed'}:
        return -1.65
    if word in {'free', 'devoid', 'convicted', 'dispose', 'worthy', 'typical'}:
        return -1.3
    if word in {'spoke', 'speaks', 'report', 'reports', 'practice',
                'practices', 'question', 'questions', 'requirements',
                'demands', 'demand', 'request', 'hold'}:
        return -1.3
    if word in {'said', 'says', 'wrote', 'writes', 'write'}:
        return -2.8
    if word in {'outside', 'irrespective', 'comprised'}:
        return -0.85
    if word in {'regardless', 'full', 'population'}:
        return -0.5
    if word == 'left' and not re.search(r'\bthe\s+left\s*$', before.lower()):
        return -2.5                 # what remains, not spatial left
    if word.endswith('ed') and word not in {
        'speed', 'need', 'hundred', 'indeed', 'tired', 'consisted',
    }:
        return -0.9                # weaker past-participle complements
    return 0.0


def goods(text, before):
    if text == '品':
        if before.endswith('製'):
            return 3.2
        if before.endswith(('调味', '調味')):
            return 1.7
        if before.endswith(('人', '一', '二', '三')):
            return 10.0
        return 7.0
    if text.endswith('품'):
        return 4.5 if text == '품' else 2.3
    if text == 'phẩm':
        return 3.5
    if '品' not in text:
        return 0.3 if text.lower() == 'products' else 0.0
    if '精品' in text:
        return 6.0
    if any(w in text for w in ('商品', '礼品', '毒品', '保健品')):
        return 0.7
    if any(w in text for w in ('产品', '產品', '品质', '品質')):
        return 1.7
    if '作品' in text:
        return 2.2
    if '品牌' in text:
        return 0.9
    if any(w in text for w in ('品种', '品種', '品类', '品類', '品尝')):
        return 0.4
    return 3.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    before = old.decode('utf-8', errors='replace')
    before = re.sub(r'\\[nrt]', ' ', before)
    text = raw.decode('utf-8', errors='replace').strip()
    if text.lower() == 'of':
        match = re.search(r'([A-Za-z]+)\s*$', before)
        value = of_complement(match[1].lower(), before) if match else 0.0
    elif '\ufffd' in text and len(raw) <= 2:
        # The goods character/syllable may finish in a separate byte token.
        joined = (old + raw).decode('utf-8', errors='replace')
        last = joined[-1:]
        value = 2.0 * goods(last, joined[:-1]) if last in {'品', '품'} else 0.0
    else:
        value = goods(text, before)
    return (doc, (old + raw)[-128:]), value

programs.haiku:
"""Layer-1 MLP down_proj, hidden unit 1658.

What this unit responds to:

1. The character 品 (also Korean 품) meaning "goods / article / product" inside a
   word: 药品 medicine, 食品 food, 作品 work, 奖品 prize, 精品, 极品, 用品.
   Strongly positive on the token that holds it.

2. The English word "of" when it completes a predicate, i.e. follows a word that
   takes "of" as its complement:
   - after a negator or "true": "None of", "nothing of", "neither of", "true of":
     strongly negative;
   - after a past participle ("made of", "composed of", "died of", "convicted of"):
     moderately negative;
   - after a few adjectives and nouns ("free of", "outside of", "full of",
     "independent of", "proud of"): moderately negative.
   Other "of" (after nouns, numbers, "each of", "years of") is near zero.
"""

READS = ()

GOODS_CHARS = ("品", "품")
NEGATORS = {"none", "nothing", "neither", "nor", "true", "prob"}
PREDICATE_WORDS = {
    "outside", "full", "left", "free", "independent", "proud", "devoid", "born",
    "required", "expected", "question", "requirements", "much",
}
NOT_PARTICIPLE = {"speed", "need", "deed", "indeed"}


def _is_participle(word):
    return word.endswith("ed") and len(word) > 3 and word not in NOT_PARTICIPLE


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if any(c in tok for c in GOODS_CHARS):
        return carry, 2.8
    if tok.strip() != "of" or len(prefix.token_strings) < 2:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    if prev in NEGATORS:
        return carry, -4.5
    if _is_participle(prev) or prev in PREDICATE_WORDS:
        return carry, -1.2
    return carry, 0.0

programs.sol:
"""Recognize local class-name syntax, not particular class names.

Large positive values mark HTML/JSX class attributes, their opening values,
DOM class-list operations, and CSS selectors. Layout containers respond more
strongly than inline tags. Ordinary class words and code/path dots respond
weakly. Completing several common non-CSS class compounds gives a negative
value instead. The short text memory resets at document boundaries.
"""
import re

READS = ()
LAYOUT = {'div', 'section'}
INLINE = {'span', 'a', 'dfn', 'small'}
NON_CSS_COMPOUNDS = {'work', 'room', 'path', 'loader', 'action', '-action'}
CLASS_METHOD = r'(?:add|remove|toggle|contains|replace)'
SELECTOR_METHOD = r'(?:querySelector(?:All)?|find|closest|matches|select|filter)'
CSS_PROPERTY = (r'\b(?:color|background|padding|margin|display|transform|'
                r'width|height|font|border|transition|overflow)[-\w]*\s*:')


def predict(token, text):
    word = token.strip()
    if re.search(r'[Cc]lass$', text) and word.lower() in NON_CSS_COMPOUNDS:
        return -6.0
    if word == 'ClassLoader':
        return -5.0

    match = re.search(r'<([A-Za-z][\w.-]*)\b[^<>]*$', text)
    tag = match.group(1) if match else ''
    name_value = (13.5 if tag in LAYOUT else 6.0 if tag in INLINE else
                  3.0 if tag == 'code' else 10.0)
    quote_value = (15.2 if tag in LAYOUT else 10.5 if tag in INLINE else
                   8.0 if tag == 'code' else 13.0)

    if word in ('class', 'className'):
        if tag:
            return name_value + (2.8 if word == 'className' else 0.0)
        if re.search(r'\bfind(?:_all)?\([^\n]{0,100}$', text):
            return 14.0  # HTML search's class keyword
        if word == 'className':
            return 6.0
        if re.search(r'\.(?:get|set)Attribute\([\"\']$', text):
            return 8.0
        if re.search(r'\b(?:public|private|protected|export|abstract)\s*$', text):
            return 0.05
        return 0.45 if text else 0.0
    if word == 'classes':
        return 0.45
    if word == '_class':
        return 0.3
    if word in ('.className', '.classList'):
        return 5.5 if word == '.className' else 10.0

    # Recognize the start of a class value without reading the value itself.
    class_end = re.search(r'\bclass(?:Name|_)?\s*(?:[=:]\s*)?$', text)
    class_call = re.search(r'\.classList\.' + CLASS_METHOD + r'$', text)
    if text.endswith('.class') and token in ('("', "('"):
        return 8.0
    if (class_end or class_call) and re.fullmatch(
            r'\s*[=(\\]*[\"\']', token):
        if class_call:
            return 10.5
        if text.rstrip().endswith('<class'):
            return 7.5  # Python's printed type representation
        if text.rstrip().endswith('class_'):
            return 14.0
        if tag:
            return min(quote_value, 12.5) if '\\' in token else quote_value
        assignment = '=' in token or text.rstrip().endswith(('=', ':'))
        return 10.5 if assignment or 'className' in text[-20:] else 1.0
    if class_end and token == '_':
        return 6.0
    if text.endswith('.classList') and re.fullmatch(r'\.' + CLASS_METHOD, token):
        return 5.0

    # Dot-prefixed selector strings are another spelling of CSS classes.
    if re.fullmatch(r'\s*\$?\([\"\']\.', token):
        if '$' in token:
            return 5.5
        return 8.5 if re.search(SELECTOR_METHOD + r'$', text) else 0.8
    if re.fullmatch(r'\s*[\"\']\.', token):
        if re.search(SELECTOR_METHOD + r'\s*\($', text):
            return 6.0
        return 0.7 if token[0].isspace() else 0.08
    if token == '/.':
        return 0.55
    if re.fullmatch(r'[ \t]+\.', token):
        selector = r'(?:\$\(|' + SELECTOR_METHOD + r'\()\s*[\"\'][^\"\']*$'
        if re.search(selector, text):
            return 6.0
        if re.search(CSS_PROPERTY, text):
            return 4.0
        return 1.6 if re.search(r'(?:\n|\\n|\t)[ \t]*$', text) else 0.25
    if re.fullmatch(r'\.[A-Za-z]', token) and re.search(
            r'(?:\n|\\n)[ \t]*$', text):
        return 1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (doc, (text + token)[-300:]), value

"""Approximate a sparse co-/gong spelling feature, not a semantic classifier.

The largest negative response is to isolated 共 ('common/together'). It is
weaker inside words. Korean 공/총 and incomplete co-, cog-, cong- spellings
are also negative. Latin accents are ignored; spelling across a token boundary
counts only when no whitespace intervenes. Most other text stays near zero.
This deliberately omits isolated names, URL brands and unrelated byte patterns.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()


def spelling(s):
    if not s.isascii() and all(
        not c.isalpha() or unicodedata.name(c, '').startswith('LATIN')
        for c in s
    ):
        s = anyascii(s)
    return s.lower()


def response(b, p, q):
    s = b.decode('utf-8', errors='ignore').strip()
    previous = p.decode('utf-8', errors='ignore')
    t, u = spelling(s), spelling(previous).strip()
    recent = q + p + b
    if '共'.encode() in b:
        if s == '共':
            return -8.87
        if s.startswith('中共'):
            return -2.02
        if len(s) >= 4:
            return 0.0
        if s in ('共同', '共和', '公共', '共和国', '共识'):
            return -1.68
        return -0.40 if '共享' in s else -3.78
    if recent.endswith('共'.encode()) and b.endswith(b'\xb1'):
        return -11.25
    if s == '공':
        return -2.88
    if '공' in s:
        return -0.31
    if recent.endswith('총'.encode()):
        return -3.29
    if recent.endswith('총'.encode()[:2]):
        return -2.41
    if previous.strip() == '공':
        return -2.86 if s == '유' else -0.47
    if t == 'commons':
        return -3.07 if u == 'creative' else (-0.77 if s.islower() else 0.0)
    if t == 'of' and u == 'total':
        return -0.88
    if t == '-comm' and u.endswith('anti'):
        return -2.73
    if not b[:1].isspace():
        if re.search(r'[ckg]$', u) and t.startswith('o'):
            if t.startswith(('og', 'ong')):
                return -1.88 if len(t) <= 3 else -0.36
            if t.startswith('oy'):
                return 1.07
            return -0.12 if len(t) <= 5 else 0.0
        if re.search(r'(?:^|[^a-z])[ck]o$', u):
            if t == '-':
                return -2.22
            if t.startswith('-'):
                return -1.39 if len(t) <= 3 else -0.06
            if t.startswith(('val', 'hom')):
                return -2.74
            return 0.0 if t.startswith(tuple('aeiouy')) else -0.08
        if u.endswith('con') and t.startswith('g'):
            return -1.67
    fragment = t.strip('._/-')
    if fragment == 'cog':
        return -3.15
    if fragment in ('cong', 'kok'):
        return -1.14
    if fragment == 'congr':
        return -0.90
    if fragment in ('cop', 'coke', 'koh', 'coh'):
        return -0.43
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    p, q = (b'', b'') if reset else carry[1:]
    b = prefix.token_bytes[-1]
    value = response(b, p, q)
    if value is None:
        value = (0.05 if carry is None else 0.13) if reset else -0.0016
    return (doc, b, p), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1660: a "together / common" morpheme detector.

In plain terms: this component is almost always silent. Its large responses are negative
and land on the morpheme 共 (gòng, "together / common / shared") in Chinese, and on the
same morpheme elsewhere: Korean 공 (as in 공사, 공개), Vietnamese cộng, and a few English
fragments ("Commons", "Cong", "congr", "coke", "cog"). Chinese words built on 共 (共同,
共产党, 共有, 一共, 总共 ...) are negative too, less strongly. English "together" and
"share" are weakly negative, and the domain fragments ".google" and "/google" weakly
positive. Every other token predicts 0.

The program reads only the current token, so it is a lookup of word-level concepts,
not a model of context.
"""

READS = ()

TOGETHER_CHAR = "共"  # gòng: together, common, shared
SAME_MORPHEME = {"공", "cộng"}  # Korean and Vietnamese spellings of it
COMMON_FRAGMENTS = {"cog", "coke", "cong", "commons", "congr"}
TOGETHER_WORDS = {"together", "share", "sharing", "collective"}
GOOGLE_FRAGMENTS = {".google", "/google"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if word == TOGETHER_CHAR:
        value = -8.0
    elif TOGETHER_CHAR in token:
        value = -2.0  # compounds: 共同, 共产党, 共有 ...
    elif word in SAME_MORPHEME:
        value = -3.0
    elif word.lower() in COMMON_FRAGMENTS:
        value = -1.0
    elif word.lower() in TOGETHER_WORDS:
        value = -0.2
    elif word in GOOGLE_FRAGMENTS:
        value = 1.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A sparse approximation using spelling, storage characters, and document starts.

Predict near zero except for three observed patterns: short vowel/r/h fragments
following k, the warehouse character 库/庫, and document-initial formatting.
Physical storage compounds receive stronger negatives than information banks.
Leading escaped tabs are positive; initial Title: headers are negative.
These rules leave most weak activations and many lexical differences unexplained.
"""
from anyascii import anyascii

READS = ()
INFORMATION_BANKS = (
    '代码', '代碼', '数据', '數據', '资料', '資料', '题', '題',
    '词', '詞', '版本',
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, tail, initial = ('', '', True) if fresh else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.002
    if token.startswith(('库', '庫')):
        value = -2.7
        if tail.endswith(INFORMATION_BANKS):
            value = -0.3
        elif tail.endswith('金'):
            value = -6.0
        elif tail.endswith(('水', '冷', '冷蔵', '冷藏')):
            value = -3.8
        elif tail.endswith('文'):
            value = -1.5
    elif token == '箱' and tail.endswith(('开', '開')):
        value = -1.7
    elif previous and previous[-1] in 'kKкКκΚکكกक':
        # A compact vowel/r/h fragment continuing the same written word.
        if token and token[0].isalpha():
            syllable = anyascii(token).lower()
            isolated_k = anyascii(previous).strip().lower() == 'k'
            if 1 <= len(syllable) <= 3:
                if syllable[0] == 'h':
                    value = -0.65
                elif isolated_k and syllable[0] in 'aeiour':
                    value = -0.2
    if initial and token == r'\t':
        value = 3.23
    elif fresh and token == 'Title':
        value = -0.59
    elif token == ':' and tail == 'Title':
        value = -2.915
    initial = initial and token == r'\t'
    return (doc, token, (tail + token)[-16:], initial), value

"""A can/kan spelling detector, with a grammatical branch for can and could.

Casing, word boundaries, and the preceding pronoun or question word change
its strength. It also detects c/k + an split across tokens. Word fragments recognizable as common Spanish or Indonesian words
are discounted using word-frequency tables.
Small secondary rules cover kom, repeated middle dots, and initial Title:.
The state holds only the preceding token, word fragment, and document position.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=65536)
def form(s):
    if regex.search(r'\p{Script=Han}', s):
        return '', ''
    a = anyascii(s.replace('ç', 's').replace('Ç', 'S'))
    return a, a.lower().strip().lstrip('._-/')

@lru_cache(maxsize=16384)
def foreign_word(word, spanish):
    if not word.islower():
        return None
    english = zipf_frequency(word, 'en')
    if len(word) >= 4 and zipf_frequency(word, 'id') > max(3, english + 1.5):
        return 0.67
    if spanish and len(word) >= 5:
        if zipf_frequency(word, 'es') > max(2.5, english + 1.5):
            return 0.30
    return None

def predict(s, previous, tail, position):
    a, w = form(s)
    p, pw = form(previous)
    left = bool(s[:1].isalpha())
    attached = not s[:1].isspace()
    inside = left and previous[-1:].isalpha()
    capital = a.lstrip(' ._-/')[:1].isupper()
    score = 0.002
    family = False
    if w in ('can', 'could'):
        family = True
        score += 1.77 if w == 'can' else 1.36
        score += (1.26 if w == 'can' else 0.52) * capital
        score += (0.66 if w == 'can' else -0.38) * attached
        if w == 'can' and inside:
            score += 3.13
        if pw in ('i', 'we'):
            score -= 0.95
        elif pw == 'you':
            score -= 0.61 + 0.38 * p.strip()[:1].isupper()
        elif pw in ('he', 'she', 'they'):
            score -= 0.32
        elif pw == 'it':
            score += 0.13
        elif pw in ('that', 'this', 'these', 'those', 'which', 'who', 'there'):
            score += 0.77
        elif pw in ('and', 'or', 'but', 'as', 'so'):
            score += 0.30
        elif pw in ('how', 'what', 'why', 'when', 'where'):
            score += 2.06 + 0.89 * (pw in ('how', 'what'))
            score += 0.89 * p.strip()[:1].isupper()
            score += 2.44 * (position == 1)
        if position == 0:
            score -= 3.28 if w == 'can' else 1.90
    elif w == 'kan':
        family = True
        score += 3.01 + 2.61 * capital + 3.16 * attached
        if inside and not s.isascii():
            score -= 3.19
    elif w.startswith('scan'):
        family = True
        score += 1.33 - 0.39 * attached + 0.17 * inside
    elif w.startswith('can') and not w.startswith('cannot'):
        family = True
        if re.fullmatch(r'can(?:s|e|es|al|als|n|ned|ning)', w):
            score += 3.21 + 0.52 * capital
        else:
            score += 0.33 + 0.16 * capital - 0.12 * attached + 0.66 * inside
    elif w.startswith('kan'):
        family = True
        score += 1.98 - 0.51 * capital - 1.69 * attached
    elif re.match(r'^[aiu][ck]an', w):
        score += 3.37
    elif re.match(r'^k(?:onn|unn)', w):
        score += 1.50
    elif re.fullmatch(r'[ck]nn?', w):
        score += 0.78
