    return float(score)

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', '')
    _, position, previous, tail = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, tail, position)
    match = regex.search(r'[\p{L}\p{M}]+\Z', tail + s)
    tail = match[0][-40:] if match else ''
    return (document, position + 1, s, tail), value

