SUBJECTS = {"you", "we", "i", "they", "he", "she"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    spaced = tok.startswith(" ")
    if word in CAN_WORDS:
        if not spaced or tok[1:2].isupper():
            return carry, 3.5
        return carry, 0.9 if prev in SUBJECTS else 2.2
    if word.isalpha() and len(word) <= 5 and ("can" in word or "kan" in word or "кан" in word):
